/// Calculate particle hashes
__global__ void calculateHashesKernel(
    Particle *particles, const size_t particleCount, float h)
{
    size_t particleIndex = blockIdx.x * blockDim.x + threadIdx.x;
    if (particleIndex >= particleCount) {
