        p->velocity.z = -p->velocity.z * BOX_COLLISION_ELASTICITY;
    }

    if (p->position.z > -settings.h + BOX_WIDTH) {
        p->position.z = -p->position.z + 2 * -(settings.h - BOX_WIDTH)
