    , settings(settings)
    , runOnGPU(runOnGPU)
{
    particleCount = particleCubeWidth * particleCubeWidth * particleCubeWidth;
    particles = (Particle*)malloc(sizeof(Particle) * particleCount);

    // Load in sphere geometry and allocate matrice space
